function unifontBits(ch) { const h = UNIFONT[ch]; if (!h) return null; const w = h.length / 4, b = new Uint8Array(256); for (let y = 0; y < 16; y++) { const row = parseInt(h.substr(y * w / 4, w / 4), 16); for (let x = 0; x < w; x++) b[y * 16 + x + (16 - w) / 2] = (row >> (w - 1 - x)) & 1; } return b; }
